import React, { useMemo, useState } from 'react';
import { useLogs } from '../../hooks/UseLogs';
import { deleteLog } from '../../api/LogsApi';
import LogFilterBar from '../../components/logs/LogFilterBar';
import LogTable from '../../components/logs/LogTable';
import LogDetailModal from '../../components/logs/LogDetailModal';

function LogsPage() {
  const { logs, loading, error, limit, setLimit, refresh } = useLogs(50);

  const [keyword, setKeyword] = useState('');
  const [riskFilter, setRiskFilter] = useState('ALL');
  const [selectedLog, setSelectedLog] = useState(null);

  const handleLimitChange = (e) => {
    const value = Number(e.target.value) || 10;
    setLimit(Math.max(10, Math.min(1000, value)));
  };

  const filteredLogs = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return logs.filter((l) => {
      const matchKeyword =
        !kw ||
        String(l.path || '').toLowerCase().includes(kw) ||
        String(l.eventType || '').toLowerCase().includes(kw) ||
        String(l.aiLabel || '').toLowerCase().includes(kw);

      const label = (l.aiLabel || '').toUpperCase();
      const matchRisk =
        riskFilter === 'ALL' ||
        (riskFilter === 'DANGER' && label === 'DANGER') ||
        (riskFilter === 'WARNING' && label === 'WARNING') ||
        (riskFilter === 'SAFE' && label === 'SAFE') ||
        (riskFilter === 'UNKNOWN' && !label);

      return matchKeyword && matchRisk;
    });
  }, [logs, keyword, riskFilter]);

  const handleDelete = async (log) => {
    await deleteLog(log.id);
    setSelectedLog(null);
    await refresh();
  };

  return (
    <div className="page-container">
      <h1>로그 관리</h1>

      <LogFilterBar
        keyword={keyword}
        onKeywordChange={setKeyword}
        riskFilter={riskFilter}
        onRiskFilterChange={setRiskFilter}
        limit={limit}
        onLimitChange={handleLimitChange}
        onRefresh={refresh}
      />

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>에러: {String(error.message || error)}</p>}

      {!loading && !error && (
        <LogTable
          logs={filteredLogs}
          onRowClick={(log) => setSelectedLog(log)}
        />
      )}

      <LogDetailModal
        log={selectedLog}
        onClose={() => setSelectedLog(null)}
        onDelete={handleDelete}
      />
    </div>
  );
}

export default LogsPage;
